123	func (s *Server) createInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
124		if !auth.CanManageTeam(p.Role) {
125			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins invite members")
126			return
127		}
128		var in struct {
129			Email string     `json:"email"`
130			Role  store.Role `json:"role"`
131		}
132		if !decode(w, r, &in) {
133			return
134		}
135		inv, err := s.store.CreateInvite(p.OrgID, in.Email, in.Role, p.UserID, s.clock.Now())
136		if err != nil {
137			s.storeError(w, err)
138			return
139		}
140		if err := s.sendInvite(r.Context(), inv); err != nil {
141			s.log.Error("send invite", "invite", inv.ID, "err", err)
142		}
143		writeJSON(w, http.StatusCreated, inv)
144	}
