170	func (s *Server) acceptInvite(w http.ResponseWriter, r *http.Request) {
171		var in struct {
172			Token string `json:"token"`
173			Name  string `json:"name"`
174		}
175		if !decode(w, r, &in) {
176			return
177		}
178		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
179		if err != nil {
180			if errors.Is(err, store.ErrNotFound) {
181				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
182				return
183			}
184			s.storeError(w, err)
185			return
186		}
187		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
188	}
