109	// AddEvent records an event.
110	func (s *Store) AddEvent(orgID, typ string, data json.RawMessage, now time.Time) (Event, error) {
111		s.mu.Lock()
112		defer s.mu.Unlock()
113		if _, ok := s.orgs[orgID]; !ok {
114			return Event{}, ErrNotFound
115		}
116		e := Event{ID: s.newID("evt"), OrgID: orgID, Type: typ, Data: append(json.RawMessage(nil), data...), CreatedAt: now.UTC()}
117		s.events[e.ID] = e
118		return e, nil
119	}
