140	// Events returns an organization's events, oldest first, only those of one type when typ is set.
141	func (s *Store) Events(orgID, typ string) []Event {
142		s.mu.Lock()
143		defer s.mu.Unlock()
144		out := []Event{}
145		for _, e := range s.events {
146			if e.OrgID == orgID && (typ == "" || e.Type == typ) {
147				out = append(out, e)
