155	func (s *Store) CreateDelivery(d Delivery, now time.Time) (Delivery, error) {
156		s.mu.Lock()
157		defer s.mu.Unlock()
158		ep, ok := s.endpoints[d.EndpointID]
159		if !ok || ep.OrgID != d.OrgID {
160			return Delivery{}, ErrNotFound
161		}
162		if e, ok := s.events[d.EventID]; !ok || e.OrgID != d.OrgID {
163			return Delivery{}, ErrNotFound
164		}
165		d.ID = s.newID("del")
166		d.CreatedAt = now.UTC()
167		if d.Status == "" {
168			d.Status = DeliveryPending
169		}
170		s.delivs[d.ID] = copyDelivery(d)
171		return copyDelivery(d), nil
172	}
